export function inner$buildCourseDailyRows$sess(c) {
    const sessions = c.sessions && c.sessions.length ? c.sessions : [{ day: c.weekday, time: c.time, label: '' }];
    const start = new Date(c.start + 'T12:00:00');
    let d = new Date(start);
    const dow = d.getDay();
    const sess = sessions.filter((ss) => ss.day === dow);
    return sess;
}
export function inner$buildCourseDailyRows$sess$$step(sessions, dow) {
    const sess = sessions.filter((ss) => ss.day === dow);
    return sess;
}
export function inner$buildCourseDailyRows$slot(ss) {
    const slot = (ss.label || 'קבוצה') + ' · ' + (ss.time || '');
    return slot;
}
export function inner$buildCourseDailyRows$active(c, db, ss) {
    const enrolls = db.enrollments.filter((e) => e.courseId === c.id);
    const start = new Date(c.start + 'T12:00:00');
    let d = new Date(start);
    const iso = isoOf(d);
    const active = enrolls.filter((e) => e.status !== 'wait' && // רשימת-המתנה לא בדוח-הנוכחות (עדיין לא לומד/ת)
        (!e.enrolledAt || e.enrolledAt <= iso) &&
        (!ss.label || !e.group || e.group === ss.label) &&
        (e.status !== 'ended' || (!!e.endedAt && iso < e.endedAt)));
    return active;
}
export function inner$buildCourseDailyRows$active$$step(enrolls, iso, ss) {
    const active = enrolls.filter((e) => e.status !== 'wait' && // רשימת-המתנה לא בדוח-הנוכחות (עדיין לא לומד/ת)
        (!e.enrolledAt || e.enrolledAt <= iso) &&
        (!ss.label || !e.group || e.group === ss.label) &&
        (e.status !== 'ended' || (!!e.endedAt && iso < e.endedAt)));
    return active;
}
export function inner$buildCourseDailyRows$mf(db, e) {
    const memberFam = new Map();
    for (const f of db.families)
        for (const m of f.members)
            memberFam.set(m.id, { first: m.first, famName: f.name });
    const mf = memberFam.get(e.memberId);
    return mf;
}
export function inner$buildCourseDailyRows$mf$$step(memberFam, e) {
    const mf = memberFam.get(e.memberId);
    return mf;
}
export function inner$buildCourseDailyRows$abs(c, e) {
    const start = new Date(c.start + 'T12:00:00');
    let d = new Date(start);
    const iso = isoOf(d);
    const abs = e.absences.find((a) => a.date === iso);
    return abs;
}
export function inner$buildCourseDailyRows$abs$$step(iso, e) {
    const abs = e.absences.find((a) => a.date === iso);
    return abs;
}
export function inner$buildCourseDailyRows$dayStatus(e) {
    const dayStatus = e.status === 'paused' ? 'מוקפא' : 'מתקיים';
    return dayStatus;
}
export function inner$buildCourseDailyRows$attend(c, e) {
    const start = new Date(c.start + 'T12:00:00');
    let d = new Date(start);
    const iso = isoOf(d);
    const abs = e.absences.find((a) => a.date === iso);
    const attend = e.status === 'paused'
        ? 'מוקפא'
        : abs
            ? abs.noshow
                ? 'לא הופיעה'
                : 'חיסור' + (abs.reason ? ' · ' + abs.reason : '')
            : 'פעיל';
    return attend;
}
export function inner$buildCourseDailyRows$attend$$step(e, abs) {
    const attend = e.status === 'paused'
        ? 'מוקפא'
        : abs
            ? abs.noshow
                ? 'לא הופיעה'
                : 'חיסור' + (abs.reason ? ' · ' + abs.reason : '')
            : 'פעיל';
    return attend;
}
export function inner$buildCourseDailyRows$memberFam$$after_loop(db) {
    const memberFam = new Map();
    for (const f of db.families)
        for (const m of f.members)
            memberFam.set(m.id, { first: m.first, famName: f.name });
    return memberFam;
}

